import{_ as a,o,c as r,ag as t}from"./chunks/framework.BXn5fPR3.js";const m=JSON.parse('{"title":"Artifacts: Kernel modules","description":"","frontmatter":{},"headers":[],"relativePath":"artifacts/modules.md","filePath":"artifacts/modules.md"}'),i={name:"artifacts/modules.md"};function s(l,e,d,n,c,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="artifacts-kernel-modules" tabindex="-1">Artifacts: Kernel modules <a class="header-anchor" href="#artifacts-kernel-modules" aria-label="Permalink to &quot;Artifacts: Kernel modules&quot;">​</a></h1><p>Drivers that plug into the Linux kernel at boot: the audio hardware driver, the infrared receiver, the watchdog, and the WiFi chipset modules. They are the lowest software layer, sitting between the operating system and the physical chips.</p><details class="details custom-block"><summary>Technical details</summary><p>Loadable kernel objects under /modules and /wifi (Atheros driver family for the SonosNet-capable radio stack).</p></details><h3 id="audiodev-ko" tabindex="-1"><code>audiodev.ko</code> <a class="header-anchor" href="#audiodev-ko" aria-label="Permalink to &quot;`audiodev.ko`&quot;">​</a></h3><p>The audio device driver: the kernel module that exposes the sound hardware to the programs above, carrying the actual digital audio to the amplifiers.</p><p><a href="/anacapad-internals/files/modules/audiodev.ko">Download</a> · 142.9 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/modules/audiodev.ko</code></li><li><strong>Category:</strong> modules</li><li><strong>Size:</strong> 142.9 KB (146328 bytes)</li><li><strong>SHA-256:</strong> <code>65bb803d74054376cad1f9305696ad0df921763981c3071fb10c70cfbf138ba4</code></li></ul><p>Core audio driver; the lla and tdm_driver entries document the interface layered on it.</p></details><h3 id="chk-ko" tabindex="-1"><code>chk.ko</code> <a class="header-anchor" href="#chk-ko" aria-label="Permalink to &quot;`chk.ko`&quot;">​</a></h3><p>The hardware-check module: a small kernel piece the system uses to verify board identity and hardware health.</p><p><a href="/anacapad-internals/files/modules/chk.ko">Download</a> · 4.6 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/modules/chk.ko</code></li><li><strong>Category:</strong> modules</li><li><strong>Size:</strong> 4.6 KB (4736 bytes)</li><li><strong>SHA-256:</strong> <code>f099055a15c41e29074bd0855c3c0add5f30d23df2a5d7c14f172bc3df00978e</code></li></ul><p>Board-check module; its device node (/dev/chk) appears in the updater&#39;s sibling-binary inventory.</p></details><h3 id="hwevent-queue-ko" tabindex="-1"><code>hwevent_queue.ko</code> <a class="header-anchor" href="#hwevent-queue-ko" aria-label="Permalink to &quot;`hwevent_queue.ko`&quot;">​</a></h3><p>The hardware-event queue: delivers physical events like button presses and jack insertions from the kernel up to the programs that handle them.</p><p><a href="/anacapad-internals/files/modules/hwevent_queue.ko">Download</a> · 17.2 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/modules/hwevent_queue.ko</code></li><li><strong>Category:</strong> modules</li><li><strong>Size:</strong> 17.2 KB (17596 bytes)</li><li><strong>SHA-256:</strong> <code>b569eb24c4d5591dd4874e2ca99b6c8109465eb442e7484c79cf08bfbe5eb2ea</code></li></ul><p>Kernel queue feeding hw_input_events / hwmessagelib, the layer that turns physical presses into internal messages.</p></details><h3 id="ir-rcvr-ko" tabindex="-1"><code>ir_rcvr.ko</code> <a class="header-anchor" href="#ir-rcvr-ko" aria-label="Permalink to &quot;`ir_rcvr.ko`&quot;">​</a></h3><p>The infrared receiver driver: the kernel piece that captures remote-control signals from the IR sensor on models that have one, like the Playbar.</p><p><a href="/anacapad-internals/files/modules/ir_rcvr.ko">Download</a> · 7.8 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/modules/ir_rcvr.ko</code></li><li><strong>Category:</strong> modules</li><li><strong>Size:</strong> 7.8 KB (7948 bytes)</li><li><strong>SHA-256:</strong> <code>467aaf41cc857a0109c1b4d124a9031c291188f238fc1f93917118f21ccff715</code></li></ul><p>IR receiver driver feeding /opt/ir config and the ir_decoder/ir_learn machinery. Absent on models without an IR sensor (a documented m8-vs-m9 difference).</p></details><h3 id="sonos-device-ko" tabindex="-1"><code>sonos_device.ko</code> <a class="header-anchor" href="#sonos-device-ko" aria-label="Permalink to &quot;`sonos_device.ko`&quot;">​</a></h3><p>The Sonos board-support module: kernel glue for the custom hardware bits specific to the player.</p><p><a href="/anacapad-internals/files/modules/sonos_device.ko">Download</a> · 3.6 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/modules/sonos_device.ko</code></li><li><strong>Category:</strong> modules</li><li><strong>Size:</strong> 3.6 KB (3640 bytes)</li><li><strong>SHA-256:</strong> <code>c5047d17c5bf529db12a3009b21c6f432d0fd51fb47f1949e83ba6bdacb2a571</code></li></ul><p>Board-support kernel module for the limelight platform.</p></details><h3 id="adf-ko" tabindex="-1"><code>adf.ko</code> <a class="header-anchor" href="#adf-ko" aria-label="Permalink to &quot;`adf.ko`&quot;">​</a></h3><p>A lower-level Atheros driver framework module the WiFi stack loads beneath the main radio driver.</p><p><a href="/anacapad-internals/files/wifi/N/adf.ko">Download</a> · 24.2 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/wifi/N/adf.ko</code></li><li><strong>Category:</strong> modules</li><li><strong>Size:</strong> 24.2 KB (24776 bytes)</li><li><strong>SHA-256:</strong> <code>7a137d22cbc1cf94d2eabe2aa093867b11d8cddb75f14aa133c6fa5f23ea4705</code></li></ul><p>Atheros Driver Framework layer for the wifi/N radio build.</p></details><h3 id="asf-ko" tabindex="-1"><code>asf.ko</code> <a class="header-anchor" href="#asf-ko" aria-label="Permalink to &quot;`asf.ko`&quot;">​</a></h3><p>Another Atheros support layer in the WiFi stack, handling shared services the radio driver relies on.</p><p><a href="/anacapad-internals/files/wifi/N/asf.ko">Download</a> · 12.8 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/wifi/N/asf.ko</code></li><li><strong>Category:</strong> modules</li><li><strong>Size:</strong> 12.8 KB (13124 bytes)</li><li><strong>SHA-256:</strong> <code>537acdbc2de81b9c75f3aed2849ad37ebaa3768c78a8671554ae4f1e0b734bf1</code></li></ul><p>Atheros Service Framework layer for the wifi/N radio build.</p></details><h3 id="ath-driver-ko" tabindex="-1"><code>ath_driver.ko</code> <a class="header-anchor" href="#ath-driver-ko" aria-label="Permalink to &quot;`ath_driver.ko`&quot;">​</a></h3><p>The main WiFi radio driver: the kernel module that actually talks to the Atheros wireless chip and does the work of joining networks and carrying traffic.</p><p><a href="/anacapad-internals/files/wifi/N/ath_driver.ko">Download</a> · 353.5 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/wifi/N/ath_driver.ko</code></li><li><strong>Category:</strong> modules</li><li><strong>Size:</strong> 353.5 KB (362008 bytes)</li><li><strong>SHA-256:</strong> <code>13e8c2658306cb55464fc942fb01d9be49b9ec53f62518367812b36454e43778</code></li></ul><p>Primary ath driver for the Atheros-based radio in this generation of hardware.</p></details><h3 id="ath-hal-ko" tabindex="-1"><code>ath_hal.ko</code> <a class="header-anchor" href="#ath-hal-ko" aria-label="Permalink to &quot;`ath_hal.ko`&quot;">​</a></h3><p>The radio&#39;s hardware-abstraction module: the closed-off layer between the open driver and the actual radio silicon.</p><p><a href="/anacapad-internals/files/wifi/N/ath_hal.ko">Download</a> · 341.5 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/wifi/N/ath_hal.ko</code></li><li><strong>Category:</strong> modules</li><li><strong>Size:</strong> 341.5 KB (349744 bytes)</li><li><strong>SHA-256:</strong> <code>bf6fa38237599dc0c7551eb8c8dd850874dc922b3db907f8bfaede36f8d9f3db</code></li></ul><p>Atheros HAL (hardware abstraction layer), the proprietary core of the driver stack.</p></details><h3 id="dfs-ko" tabindex="-1"><code>dfs.ko</code> <a class="header-anchor" href="#dfs-ko" aria-label="Permalink to &quot;`dfs.ko`&quot;">​</a></h3><p>The radar-detection module: watches for radar on restricted WiFi channels so the speaker can legally operate on them, part of the 5 GHz regulatory machinery.</p><p><a href="/anacapad-internals/files/wifi/N/dfs.ko">Download</a> · 56.7 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/wifi/N/dfs.ko</code></li><li><strong>Category:</strong> modules</li><li><strong>Size:</strong> 56.7 KB (58024 bytes)</li><li><strong>SHA-256:</strong> <code>7721e59669177601410ee881d03d935ddc7b33edb6ece2c618bce130773debd1</code></li></ul><p>DFS (Dynamic Frequency Selection) module; pairs with the radartool utility.</p></details><h3 id="bridge-ko" tabindex="-1"><code>bridge.ko</code> <a class="header-anchor" href="#bridge-ko" aria-label="Permalink to &quot;`bridge.ko`&quot;">​</a></h3><p>The network-bridge module: lets the speaker bridge wired and wireless interfaces so SonosNet members can share a connection.</p><p><a href="/anacapad-internals/files/wifi/bridge.ko">Download</a> · 76.2 KB</p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/wifi/bridge.ko</code></li><li><strong>Category:</strong> modules</li><li><strong>Size:</strong> 76.2 KB (78056 bytes)</li><li><strong>SHA-256:</strong> <code>1f738329dd9016b52f1872a5fde659ca2291fca638253adc94024fb52215252a</code></li></ul><p>Kernel bridge support used by brctl in the SonosNet topology.</p></details>',47)])])}const f=a(i,[["render",s]]);export{m as __pageData,f as default};
